import sys

def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def find_prime_position(n):
    count = 0
    for i in range(1, n + 1):
        if is_prime(i):
            count += 1
    return count

# Position to find
