```csharp
public static string InsertCharacterAtIndex(string input, char character, int index)
{
    if (index < 0 || index >= input.Length) {
        throw new ArgumentException("Index must be between 0 and the length of the string.");
    }

    string result = new string(input.ToCharArray());
    result = result.Substring(0, index) + character + result.Substring(index + 1);
    return result;
}
```

